package com.flow.focus.platform

/** Audio catalogue information displayed in the settings UI. */
data class AmbientSoundInfo(val id: String, val label: String, val hint: String)

/**
 * Backward-compatible name retained for existing Settings and timer references.
 * Playback and audio generation are now handled by Media3 using AmbientLibrary field recordings.
 * No synthesized audio is generated by the active application path.
 */
object AmbientSynth {
    const val NONE = "none"

    val sounds: List<AmbientSoundInfo> = AmbientLibrary.recordings.map { recording ->
        AmbientSoundInfo(recording.id, recording.title, recording.hint)
    }
}
